import re
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from roman import to_roman, from_roman


# ---- obviously-correct reference model for to_roman ----
_THOUSANDS = ["", "M", "MM", "MMM"]
_HUNDREDS = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
_TENS = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
_ONES = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]

def ref_to_roman(n: int) -> str:
    return (
        _THOUSANDS[n // 1000]
        + _HUNDREDS[(n % 1000) // 100]
        + _TENS[(n % 100) // 10]
        + _ONES[n % 10]
    )

_VALID_CHARS = set("IVXLCDM")


# ---- concrete examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_LVIII():
    assert from_roman("LVIII") == 58

def test_example_from_roman_IIII_raises():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_raises():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- to_roman type strictness ----
def test_to_roman_rejects_bool():
    for b in [True, False]:
        with pytest.raises(TypeError):
            to_roman(b)

def test_to_roman_rejects_non_int_types():
    for bad in [4.0, 4.5, "IV", "4", None, [4], (4,), 4.0, float("nan")]:
        with pytest.raises(TypeError):
            to_roman(bad)

@given(st.one_of(
    st.floats(allow_nan=True, allow_infinity=True),
    st.text(max_size=8),
    st.none(),
    st.booleans(),
    st.lists(st.integers()),
    st.tuples(st.integers()),
))
def test_to_roman_type_property_bad_types_raise_TypeError(v):
    assume(not isinstance(v, int) or isinstance(v, bool))
    # if v happens to be int-like but bool, still TypeError; otherwise non-int -> TypeError
    if isinstance(v, bool) or not isinstance(v, int):
        with pytest.raises(TypeError):
            to_roman(v)

def test_to_roman_range_boundaries():
    with pytest.raises(ValueError):
        to_roman(0)
    with pytest.raises(ValueError):
        to_roman(-1)
    with pytest.raises(ValueError):
        to_roman(-3999)
    with pytest.raises(ValueError):
        to_roman(4000)
    with pytest.raises(ValueError):
        to_roman(5000)
    # valid edges must not raise
    assert isinstance(to_roman(1), str)
    assert isinstance(to_roman(3999), str)

@given(st.integers())
def test_to_roman_range_property(n):
    assume(n < 1 or n > 3999)
    # exclude bools: bools are ints in Python but must raise TypeError, not ValueError
    assume(not isinstance(n, bool))
    with pytest.raises(ValueError):
        to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_output_shape(n):
    s = to_roman(n)
    assert isinstance(s, str)
    assert s != ""
    assert s == s.upper()
    assert set(s) <= _VALID_CHARS
    # only allowed subtractive pairs may appear
    # no lowercase, no whitespace
    assert " " not in s and "\n" not in s and "\t" not in s
    # canonical never uses IIII, XXXX, CCCC, MMMM
    for bad in ("IIII", "XXXX", "CCCC", "MMMM", "VV", "LL", "DD"):
        assert bad not in s

def test_to_roman_full_range_reference():
    # exhaustive check of all canonical values against reference
    for n in range(1, 4000):
        assert to_roman(n) == ref_to_roman(n)


# ---- from_roman type strictness ----
def test_from_roman_rejects_non_str():
    for bad in [1, 4, 58, 4.0, None, True, False, ["X"], ("X",), b"X", bytearray(b"X")]:
        with pytest.raises(TypeError):
            from_roman(bad)

@given(st.one_of(
    st.integers(), st.floats(allow_nan=True, allow_infinity=True),
    st.none(), st.booleans(), st.lists(st.text(max_size=3)),
    st.binary(max_size=5),
))
def test_from_roman_type_property(v):
    assume(not isinstance(v, str))
    with pytest.raises(TypeError):
        from_roman(v)


# ---- from_roman strictness ----
def test_from_roman_rejects_empty():
    with pytest.raises(ValueError):
        from_roman("")

def test_from_roman_rejects_lowercase():
    with pytest.raises(ValueError):
        from_roman("iv")
    with pytest.raises(ValueError):
        from_roman("mcmxciv")

def test_from_roman_rejects_whitespace():
    for s in [" X", "X ", "X\n", "\tX", "X\t", "X X", "\n", " ", "M C"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_noncanonical_examples():
    for s in ["IIII", "VV", "IC", "XM", "IXI", "MMMM", "XXXX", "CCCC",
              "DD", "LL", "VL", "IL", "IM", "XD", "VX", "LC", "DM", "IIV", "VIV"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_unknown_chars():
    for s in ["A", "X1", "M!", "IV?", "123", "MMMMM", "NNNN"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_four_X_defect():
    # regression: tens digit must never allow XXXX
    with pytest.raises(ValueError):
        from_roman("XXXX")
    with pytest.raises(ValueError):
        from_roman("LXXXX")
    with pytest.raises(ValueError):
        from_roman("XXXXX")

def test_from_roman_rejects_embedded_four_X():
    for s in ["MXXXX", "MMXXXX", "CXXXX", "MCXXXX", "DXXXX", "DCXXXX"]:
        with pytest.raises(ValueError):
            from_roman(s)

@given(st.sampled_from(["XXXX", "LXXXX", "XXXXX", "MXXXX", "CXXXX"]))
def test_from_roman_four_X_property(s):
    with pytest.raises(ValueError):
        from_roman(s)

@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=6))
def test_from_roman_accept_implies_roundtrip(s):
    # strict inverse: accepted strings must be fixed points of to_roman∘from_roman
    try:
        n = from_roman(s)
    except ValueError:
        return
    assert isinstance(n, int)
    assert not isinstance(n, bool)
    assert 1 <= n <= 3999
    assert to_roman(n) == s

@given(st.text(alphabet="IVXLCDMivxlcdm 012 \t\n", min_size=0, max_size=8))
def test_from_roman_fuzz_accept_implies_canonical(s):
    try:
        n = from_roman(s)
    except ValueError:
        return
    # every accepted string must equal canonical form of its value
    assert s == ref_to_roman(n)
    assert s == to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_to_from(n):
    assert from_roman(to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_from_to_via_reference(n):
    s = ref_to_roman(n)
    assert from_roman(s) == n
    assert to_roman(from_roman(s)) == s

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_in_range(n):
    v = from_roman(to_roman(n))
    assert isinstance(v, int)
    assert not isinstance(v, bool)
    assert 1 <= v <= 3999

def test_from_roman_known_values():
    cases = {
        "I": 1, "II": 2, "III": 3, "IV": 4, "V": 5, "VI": 6, "IX": 9,
        "X": 10, "XL": 40, "L": 50, "XC": 90, "C": 100, "CD": 400,
        "D": 500, "CM": 900, "M": 1000, "LVIII": 58, "MCMXCIV": 1994,
        "MMMCMXCIX": 3999, "MMXXIV": 2024, "XLII": 42, "XCIX": 99,
        "DCCC": 800, "LXXX": 80, "VIII": 8, "XXXIX": 39,
    }
    for s, n in cases.items():
        assert from_roman(s) == n
        assert to_roman(n) == s

def test_to_roman_known_values():
    assert to_roman(1) == "I"
    assert to_roman(2) == "II"
    assert to_roman(3) == "III"
    assert to_roman(5) == "V"
    assert to_roman(9) == "IX"
    assert to_roman(40) == "XL"
    assert to_roman(50) == "L"
    assert to_roman(90) == "XC"
    assert to_roman(400) == "CD"
    assert to_roman(500) == "D"
    assert to_roman(900) == "CM"
    assert to_roman(58) == "LVIII"
